/** From this date (on the sheet's today) a claim opened is numbered within its period; null: off. */
@Column(name = "period_numbering_from")
private LocalDate periodNumberingFrom;

/** The default date of a new claim in place of the sheet's today; null: off. Not dated. */
@Column(name = "entry_date")
private LocalDate entryDate;

/** Days past an open period's to-date after which a change of today closes it; null: off. Not dated. */
@Column(name = "grace_days")
private Integer graceDays;

/** The month (1 to 12) the sheet's fiscal year starts in. Not dated. */
@Column(name = "fiscal_start_month", nullable = false)
private int fiscalStartMonth = 1;

/** The pot shared out over each balanced pool's members by their shares; null: none. Not dated. */
@Column(name = "pot")
private BigDecimal pot;

/** The due-total above which a person's due-total crossing it is reported in an ALERT line; null: off. Not dated. */
@Column(name = "alert_threshold")
private BigDecimal alertThreshold;

/** The id of the parent sheet whose rates a grade with none in force here falls back on; null: none. Not dated. */
@Column(name = "parent")
private String parent;

/** Whether a steward archived the sheet: everything stays visible and every change is refused. */
@Column(name = "archived", nullable = false)
private boolean archived;

/** The number of the sheet's last bulk settle batch: 0 while there has been none. Moved on only through the repository. */
@Column(name = "last_settle_batch", nullable = false, insertable = false, updatable = false)
private long lastSettleBatch;

protected Sheet() {
}

public Sheet(String id, String createdBy, LocalDate today) {
    this.id = id;
    this.createdBy = createdBy;
    this.today = today;
}

/**
 * A copy of the sheet under another id: its today, dated settings, permission matrix and other settings; not
 * archived, with no settle batch yet.
 */
public Sheet copyTo(String id, String createdBy) {
    Sheet copy = new Sheet(id, createdBy, today);
    dated.forEach(d -> copy.dated.add(new DatedSetting(copy, d.getKey(), d.getFromDate(), d.getValue())));
    copy.permissions.putAll(permissions);
    copy.policyDate = policyDate;
    copy.periodNumberingFrom = periodNumberingFrom;
    copy.entryDate = entryDate;
    copy.graceDays = graceDays;
    copy.fiscalStartMonth = fiscalStartMonth;
    copy.pot = pot;
    copy.alertThreshold = alertThreshold;
    copy.parent = parent;
    return copy;
}

public String getId() {
public void setEntryDate(LocalDate entryDate) {
    this.entryDate = entryDate;
}

/** The default date of a new claim: the entry date while it is set, else the sheet's today. */
public LocalDate entryDateOrToday() {
    return entryDate != null ? entryDate : today;
}

public Integer getGraceDays() {
    return graceDays;
}

public void setGraceDays(Integer graceDays) {
    this.graceDays = graceDays;
}

public int getFiscalStartMonth() {
    return fiscalStartMonth;
}

public void setFiscalStartMonth(int fiscalStartMonth) {
    this.fiscalStartMonth = fiscalStartMonth;
}

/** The name (FYyyyy) of the fiscal year the date falls in: the calendar year of that fiscal year's first day. */
public String fiscalYearOf(LocalDate date) {
    return fiscalYearOf(date, fiscalStartMonth);
}

/** The name (FYyyyy) of the fiscal year the date falls in when fiscal years start in the month (1 to 12). */
public static String fiscalYearOf(LocalDate date, int startMonth) {
    return "FY" + (date.getMonthValue() >= startMonth ? date.getYear() : date.getYear() - 1);
}

public BigDecimal getPot() {
    return pot;
}

public void setPot(BigDecimal pot) {
    this.pot = pot;
}

public BigDecimal getAlertThreshold() {
    return alertThreshold;
}

public void setAlertThreshold(BigDecimal alertThreshold) {
    this.alertThreshold = alertThreshold;
}

public String getParent() {
    return parent;
}

public void setParent(String parent) {
    Sheet sheet = get(sheetId);
    sheet.setPermission(action, roles);
    Sheet saved = sheets.saveAndFlush(sheet);
    audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=perm-" + action + " value="
            + (roles == null ? "" : roles));
    return saved;
}

/** Set the grace days; null means off. Every save is recorded, even of the same value. */
@Transactional
public Sheet setGraceDays(String sheetId, String user, Integer graceDays) {
    Sheet sheet = get(sheetId);
    sheet.setGraceDays(graceDays);
    Sheet saved = sheets.saveAndFlush(sheet);
    audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=grace-days value="
            + (graceDays == null ? "" : graceDays.toString()));
    return saved;
}

/** Set the fiscal year start month (1 to 12). Every save is recorded, even of the same value. */
@Transactional
public Sheet setFiscalStartMonth(String sheetId, String user, int month) {
    Sheet sheet = get(sheetId);
    sheet.setFiscalStartMonth(month);
    Sheet saved = sheets.saveAndFlush(sheet);
    audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=fiscal-start-month value=" + month);
    return saved;
}

/** Set the pot, shared out over each balanced pool's members; null means none. Every save is recorded, even of the same value. */
@Transactional
public Sheet setPot(String sheetId, String user, BigDecimal pot) {
    Sheet sheet = get(sheetId);
    sheet.setPot(pot);
    Sheet saved = sheets.saveAndFlush(sheet);
    audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=pot value="
            + (pot == null ? "" : pot.toPlainString()));
    return saved;
}

/**
 * Set the alert threshold, above which a person's due-total going is reported in an ALERT line; null means off.
 * Every save is recorded, even of the same value.
 */
@Transactional
public Sheet setAlertThreshold(String sheetId, String user, BigDecimal threshold) {
    Sheet sheet = get(sheetId);
    sheet.setAlertThreshold(threshold);
    Sheet saved = sheets.saveAndFlush(sheet);
    audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=alert-threshold value="
            + (threshold == null ? "" : threshold.toPlainString()));
    return saved;
}

/**
 * Set the parent sheet, whose rates a grade with none in force on a date here falls back on; null means none.
/**
 * The settings as shown, each dated one as in force on the sheet's today: the clerk limit with two decimals, null
 * when there is none; the floor with two decimals; the terms in whole days; each grade's own terms in whole days,
 * by grade (a grade without its own is left out); the late percent with two decimals; the policy date as
 * yyyy-mm-dd, null when blank (the sheet's today); the period numbering from as yyyy-mm-dd, null when blank (off);
 * the entry date as yyyy-mm-dd, null when blank (off); the cap with two decimals, null when there is none; the grace days in whole days, null when blank (off); the fiscal year start month (1 to 12); the proof threshold with two decimals, null when there is none; the note threshold with two decimals, null when there is none; the review threshold with two decimals, null when there is none; the pot with two decimals, null when there is none; the alert threshold with two decimals, null when off; the parent sheet's id, null when there is none;
 * the permission matrix, by action (open, settle, void, reassign, close, reopen), the roles entered for it comma
 * separated, null when blank (the standing rule).
 * Then every value recorded of each dated setting, by key (clerk-limit, floor, terms, terms-A, terms-B, terms-C,
 * grace-A, grace-B, grace-C, late-pct, cap, proof-threshold, proof-threshold-A, proof-threshold-B, proof-threshold-C, note-threshold, review-threshold, rounding), from-date first to last.
 */
public record SettingsView(String clerkLimit, String floor, int terms, Map<String, Integer> gradeTerms,
        String latePct, LocalDate policyDate, LocalDate periodNumberingFrom, LocalDate entryDate, String cap,
        Integer graceDays, int fiscalStartMonth, String proofThreshold, String noteThreshold, String reviewThreshold, String pot, String alertThreshold, String parent, Map<String, String> permissions, Map<String, List<DatedValue>> dated) {

    static SettingsView of(Sheet sheet, Map<String, Integer> gradeTerms) {
        LocalDate today = sheet.getToday();
        Map<String, List<DatedValue>> dated = new LinkedHashMap<>();
        sheet.datedSettings().forEach((key, values) -> dated.put(key,
                values.stream().map(d -> new DatedValue(d.getFromDate(), d.getValue())).toList()));
        Map<String, String> permissions = new LinkedHashMap<>();
        Sheet.PERMISSION_ACTIONS.forEach(action -> permissions.put(action, sheet.permission(action)));
        return new SettingsView(shown(sheet.getClerkLimit()), shown(sheet.floorOn(today)), sheet.termsOn(today),
                gradeTerms, shown(sheet.latePctOn(today)), sheet.getPolicyDate(), sheet.getPeriodNumberingFrom(),
                sheet.getEntryDate(), shown(sheet.getCap()), sheet.getGraceDays(), sheet.getFiscalStartMonth(), shown(sheet.proofThresholdOn(today)),
                shown(sheet.noteThresholdOn(today)), shown(sheet.reviewThresholdOn(today)), shown(sheet.getPot()), shown(sheet.getAlertThreshold()), sheet.getParent(), permissions,
                dated);
    }

    private static String shown(BigDecimal value) {
        return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
}

/** A policy date as yyyy-mm-dd; null (blank) means the sheet's today. */
public record PolicyDateRequest(LocalDate policyDate) {
}

/** Grace days of 0 or more whole days; blank or missing means off. */
public record GraceDaysRequest(@Pattern(regexp = "\\s*(\\d{1,5})?\\s*") String graceDays) {

    Integer graceDaysValue() {
        return graceDays == null || graceDays.isBlank() ? null : Integer.valueOf(graceDays.trim());
    }
}

/** A fiscal year start month, 1 to 12. */
public record FiscalStartMonthRequest(@NotNull @Pattern(regexp = "\\s*(0?[1-9]|1[0-2])\\s*") String fiscalStartMonth) {
@PutMapping("/entry-date")
public SettingsView setEntryDate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
        @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
        @RequestBody EntryDateRequest request) {
    return view(service.setEntryDate(sheetId.trim(), user.trim(), request.entryDate()));
}

@PutMapping("/grace-days")
public SettingsView setGraceDays(@PathVariable @NotBlank @Size(max = 100) String sheetId,
        @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
        @RequestBody @Valid GraceDaysRequest request) {
    return view(service.setGraceDays(sheetId.trim(), user.trim(), request.graceDaysValue()));
}

@PutMapping("/fiscal-start-month")
public SettingsView setFiscalStartMonth(@PathVariable @NotBlank @Size(max = 100) String sheetId,
        @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
        @RequestBody @Valid FiscalStartMonthRequest request) {
    return view(service.setFiscalStartMonth(sheetId.trim(), user.trim(), request.fiscalStartMonthValue()));
}

@PutMapping("/pot")
public SettingsView setPot(@PathVariable @NotBlank @Size(max = 100) String sheetId,
        @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
        @RequestBody @Valid PotRequest request) {
    return view(service.setPot(sheetId.trim(), user.trim(), request.potValue()));
}

@PutMapping("/alert-threshold")
public SettingsView setAlertThreshold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
        @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
        @RequestBody @Valid AlertThresholdRequest request) {
    return view(service.setAlertThreshold(sheetId.trim(), user.trim(), request.alertThresholdValue()));
}

@PutMapping("/parent")

